#!/usr/bin/env python3
"""Build the portable manual Marketing launch Module using existing AM bricks."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
DEST=ROOT/'module/agents/main'
BROKER='recipe--application_data_v1'
DOMAIN=(ROOT/'domain.js').read_text().replace('export ','')
RUNTIME=(ROOT/'runtime.js').read_text()
OPS={'campaign-save':('Marketing — campagne','campaign','cib_marketing'),'content-link':('Marketing — lier les preuves et le contenu','content','cib_marketing'),'request':('Marketing — demande d’essai','request','cib_marketing'),'progress':('Accompagnement — progression de l’essai','support','cib_service_client'),'read':('Marketing — lire une fiche',None,'cib_dossiers'),'list':('Marketing — liste accessible',None,'cib_dossiers'),'people':('Marketing — membres partageables',None,'cib_dossiers'),'share':('Marketing — partager ou retirer un accès','sharing','cib_dossiers'),'summary':('Direction — lancement et premiers résultats','direction','cib_direction')}
OPTIONS={'jeu':[('usage','Travail réel'),('qualification','Essais synthétiques')],'kind':[('campaign','Campagne'),('trial','Essai')],'permission':[('read','Lecture'),('write','Modification'),('none','Retirer')],'phase':[('en_cours','En cours'),('bloque','Bloqué'),('premier_resultat_confirme','Premier résultat confirmé (attestation interne)')],'confirmation_manuelle':[('non','Non'),('oui','Oui')],'confirmation_resultat':[('non','Non'),('oui','Oui, déclaration et preuve relues')]}
TITLES={'jeu':'Jeu','campaign_id':'Identifiant de campagne','trial_id':'Identifiant de l’essai','id':'Identifiant de la fiche','kind':'Type de fiche','objectif':'Objectif','audience':'Public visé','promesse':'Message et promesse bornée','canal':'Canal prévu (aucune diffusion)','responsable':'Responsable opérationnel','echeance':'Échéance (AAAA-MM-JJ)','critere_fin':'Critère de premier résultat','expected_revision':'Révision attendue','campaign_revision':'Révision de la campagne','veille_ref':'Fiche Veille','veille_revision':'Révision Veille','contenu_ref':'Fiche Contenu','contenu_revision':'Révision Contenu','preuve_ref':'Référence de preuve de la revue','personne_ref':'Référence interne de la personne','besoin':'Besoin déclaré','phase':'Étape de l’essai','accompagnement_ref':'Fiche Accompagnement','accompagnement_revision':'Révision Accompagnement','date_confirmation':'Date de la déclaration (AAAA-MM-JJ)','confirmation_resultat':'Premier résultat déclaré et preuve relue','subject_user_id':'Membre existant','permission':'Droit sur cette fiche','confirmation_manuelle':'Je confirme cette opération interne'}
MEMOS={'objectif','audience','promesse','critere_fin','besoin'}
FIELDS={'campaign':['jeu','campaign_id','objectif','audience','promesse','canal','responsable','echeance','critere_fin','expected_revision','confirmation_manuelle'],'content':['jeu','campaign_id','expected_revision','veille_ref','veille_revision','contenu_ref','contenu_revision','preuve_ref','confirmation_manuelle'],'request':['jeu','campaign_id','campaign_revision','trial_id','personne_ref','besoin','objectif','confirmation_manuelle'],'support':['jeu','trial_id','expected_revision','phase','accompagnement_ref','accompagnement_revision','date_confirmation','confirmation_resultat','confirmation_manuelle'],'sharing':['jeu','kind','id','expected_revision','subject_user_id','permission','confirmation_manuelle'],'direction':['jeu']}
OPTIONAL={'date_confirmation'}
MAP={'campaign':'campaign-save','content':'content-link','request':'request','support':'progress','sharing':'share','direction':'summary'}
def dump(path,value):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def field(name):
    f={'name':name,'title':TITLES[name],'type':'select' if name in OPTIONS else 'text' if name in MEMOS else 'string','required':name not in OPTIONAL,'default':'{{ state.selected.prefill.'+name+' }}'}
    if name in OPTIONS:f['options']=[{'value':v,'label':l} for v,l in OPTIONS[name]]
    return f
OUTPUTS=['record','revision','owner_user_id','permissions','permissions_summary','shares','share_count','rows','items','people','selected_target','summary','prefill','effects','replayed','message','scope','validation_mode','external_effect']
def workflow(op):
    title,form,role=OPS[op]
    w={'$schema':'agentmaurice.workflow/v2','schema_version':2,'kind':'workflow','workflow_id':'cib-launch-'+op,'version':'1','title':title,'description':'Parcours manuel interne ; données et droits contrôlés par le broker AM existant.','actions':[{'id':'run','type':'code_execution','context':{'allowed_tools':[BROKER]},'code':"import { callTool } from './tools/nats_bridge.ts';\nconst input={{ json . }};\n"+DOMAIN+'\n'+RUNTIME+"\nreturn await execute('"+op+"',input);",'output_key':'result'}],'output':{k:'{{ result.'+k+' }}' for k in OUTPUTS}}
    if form:w['forms']=[{'id':form,'title':title,'fields':[field(n) for n in FIELDS[form]],'actions_on_submit':['run']}]
    return w
GUIDES={'campaign':'1. Créez une campagne. L’identifiant et le jeu sont stables ; indiquez 0 à la création. Modifier le brief remet le contenu en revue.','content':'2. Préparez les fiches Veille et Contenu dans les rôles existants. Sélectionnez une campagne, puis liez leurs identifiants et révisions exactes avec une preuve de revue. Aucune publication.','request':'3. Sélectionnez une campagne prête, puis enregistrez une demande avec un identifiant d’essai stable. Le rejeu identique ne crée pas de doublon. Partagez la fiche d’essai en modification avec la personne chargée de l’accompagnement.','support':'4. Le rôle Accompagnement prépare sa fiche existante. Sélectionnez l’essai explicitement partagé, passez-le en cours, puis reliez le résultat déclaré, sa preuve et sa date. Une déclaration interne ne prouve ni vente ni publication.','sharing':'Partagez une seule fiche : sélectionnez-la, chargez les membres, puis cliquez la personne pour ouvrir le formulaire. Retirez avec « Retirer ». Partager ne donne pas le droit d’utiliser un service ni de gérer les partages.','direction':'5. Cette synthèse compte uniquement vos fiches accessibles. Demandes et premiers résultats sont distincts. Attribution, conversion et gain de temps restent non mesurés.'}
def miniapp(form):
    defaults={n:'' for n in FIELDS[form]};defaults.update({'jeu':'usage','expected_revision':'0','campaign_revision':'0','confirmation_manuelle':'non','confirmation_resultat':'non','permission':'read','kind':'campaign','phase':'en_cours'})
    events=[];layout=[{'type':'text','value':GUIDES[form]},{'type':'text','value':'Ouvrez le formulaire par son titre dans les interactions disponibles. Les champs longs sont des mémos. Le responsable indiqué ne crée aucun droit AM.'}]
    for game,label in [('usage','Actualiser le travail réel'),('qualification','Actualiser les essais')]:
        eid='refresh-'+game;layout.append({'type':'button','label':label,'on_click':eid});events.append({'event_id':eid,'trigger':'action.click','workflow':{'workflow_id':'cib-launch-'+('summary' if form=='direction' else 'list'),'input':{'jeu':game,'kind':'trial' if form=='support' else 'campaign' if form in ['campaign','content'] else 'all'}},'result_to_state':'listing'})
    layout += [{'type':'text','value':{'state':'listing.message'}},{'type':'table','columns':['kind','id','phase','revision','objectif'],'rows':{'state':'listing.items'},**({} if form=='direction' else {'on_row_click':'select'})}]
    if form!='direction':
        events.append({'event_id':'select','trigger':'table.row_click','workflow':{'workflow_id':'cib-launch-read','input':{'jeu':'{{ event.payload.item.jeu }}','kind':'{{ event.payload.item.kind }}','id':'{{ event.payload.item.id }}','form_id':form}},'result_to_state':'selected'})
        layout += [{'type':'text','value':{'state':'selected.message'}},{'type':'text','value':{'state':'selected.permissions_summary'}},{'type':'text','value':{'state':'selected.record.objectif'}},{'type':'text','value':{'state':'selected.record.resultat_observe'}},{'type':'text','value':{'state':'selected.record.preuve_ref'}}]
    if form=='sharing':
        layout += [{'type':'button','label':'Charger les membres existants','on_click':'people'},{'type':'table','columns':['user_id','display_name'],'rows':{'state':'people.people'},'on_row_click':'choose'}]
        base={'jeu':'{{ state.selected.record.jeu }}','kind':'{{ state.selected.record.kind }}','id':'{{ state.selected.record.id }}'}
        events += [{'event_id':'people','trigger':'action.click','workflow':{'workflow_id':'cib-launch-people','input':base},'result_to_state':'people'},{'event_id':'choose','trigger':'table.row_click','workflow':{'workflow_id':'cib-launch-people','input':{**base,'subject_user_id':'{{ event.payload.item.user_id }}'}},'result_to_state':'people'}]
    if form=='direction':
        for name,label in [('campagnes_accessibles','Campagnes accessibles'),('demandes_accessibles','Demandes d’essai accessibles'),('premiers_resultats_confirmes','Premiers résultats attestés')]:layout.append({'type':'section','title':label,'children':[{'type':'text','value':{'state':'listing.summary.'+name}}]})
    events.append({'event_id':'save','trigger':'form.submit','workflow':{'workflow_id':'cib-launch-'+MAP[form],'input':{n:'{{ state.'+n+' }}' for n in FIELDS[form]}},'result_to_state':'listing' if form=='direction' else 'selected'})
    properties={n:{'type':'string'} for n in sorted(set(defaults)|set(FIELDS[form]))};properties.update({n:{'type':'object'} for n in ['listing','selected','people']})
    return {'$schema':'agentmaurice.miniapp/v2','schema_version':2,'kind':'miniapp','miniapp_id':'cib-launch-'+form+'-console','version':'1','title':OPS[MAP[form]][0],'description':GUIDES[form],'ui':{'renderer':'component','component':'company-in-a-box','configuration':{'layout':layout}},'state_schema':{'type':'object','properties':properties},'initial_state':{**defaults,'listing':{'items':[],'message':'Aucune liste chargée.','summary':{}},'selected':{'record':{},'prefill':defaults,'message':'Aucune fiche sélectionnée.'},'people':{'people':[]}},'events':events}
def build():
    for op in OPS:dump(DEST/'workflows'/('cib-launch-'+op+'.json'),workflow(op))
    for form in MAP:dump(DEST/'miniapps'/('cib-launch-'+form+'-console.json'),miniapp(form))
    manifest={'$schema':'agentmaurice.module/v2','schema_version':2,'key':'cib-marketing-launch','name':'Company in a Box — Marketing de lancement','version':'0.1.0','provides':{'actions':[],'queries':[],'apps':[]},'requires':{}}
    for op in OPS:manifest['provides']['queries' if op in ['read','list','people','summary'] else 'actions'].append({'key':op,'workflow_id':'cib-launch-'+op,'workflow_version':'1'})
    for form in MAP:manifest['provides']['apps'].append({'key':form,'miniapp_id':'cib-launch-'+form+'-console','miniapp_version':'1'})
    dump(ROOT/'module/module.yaml',manifest)
    cases=[]
    valid={'jeu':'qualification','campaign_id':'mkt-technical-denied','objectif':'Qualification','audience':'Fictive','promesse':'Aucune promesse publique','canal':'interne','responsable':'test','echeance':'2026-12-31','critere_fin':'Qualification interne','expected_revision':'0','confirmation_manuelle':'oui'}
    for op,inp in [('campaign-save',valid),('read',{'jeu':'qualification','kind':'campaign','id':'mkt-technical-denied','form_id':'campaign'}),('list',{'jeu':'qualification','kind':'all'}),('summary',{'jeu':'qualification'})]:cases.append({'id':'launch-technical-denied-'+op,'description':'Le broker doit refuser une exécution technique sans identité humaine ; cas positifs par sessions CIB.','workflow':{'workflow_id':'cib-launch-'+op,'input':inp},'assertions':[{'type':'status','expected':'failed'}]})
    dump(ROOT/'module/test-plan.json',{'$schema':'agentmaurice.test_plan/v2','schema_version':2,'test_plan_id':'cib-marketing-launch','cases':cases})
    dump(ROOT/'service-gates.json',{'workflows':{'cib-launch-'+op:role for op,(_,_,role) in OPS.items()}})
if __name__=='__main__':build()
